    true_naeun: { title: '창밖에서 만나자', rank: 'S', bg: 'hospital', c: 'naeun', e: 'smile',
      t: '4월, 벚꽃병원 정원. 약속나무는 이번엔 제때 피었다가 제때 졌다. 휠체어에 앉은 여자애가 창밖이 아니라, 정원의 벚꽃을 올려다보고 있었다. 머리칼 끝에 보랏빛은 없었다. 대신 눈가의 점은 같은 자리에 있었다. 수술은 성공했다고 했다. "…처음 뵙겠습니다." 그 애가 말했다. 나는 플래너를 펴서 보여 주었다. 매일 맨 윗줄, 이나은. 그 애의 눈이 커졌다가, 천천히 젖었다. "…오랜만이야. 이번에는, 처음이 아니구나." 여섯 번째 봄은 오지 않았다. 대신 스무 살의 봄이 왔다.' },
    normal_naeun: { title: '이름 없는 기억', rank: 'B', bg: 'school_gate_sakura', c: 'naeun', e: 'smile',
      t: '대학 입학식 날, 교정의 벚꽃 아래서 이유 없이 눈물이 났다. 가끔 비가 오기 직전, 누군가 "4시 12분"이라고 속삭이는 것 같다. 그래서 나는 이제 늘 우산을 두 개 가지고 다닌다. 누구에게 주려는 건지도 모르면서. 어느 봄날, 학교 앞 병원에서 퇴원하는 여자애와 눈이 마주쳤다. 그 애가 멈춰 서서, 아주 오래 나를 보았다. 무언가 말하려다 웃고 지나간 그 애의 뒷모습을, 나는 한참 동안 바라보았다.' },
    bad_naeun: { title: '여섯 번째 봄', rank: 'BAD', bg: 'classroom', c: 'naeun', e: 'sad',
      t: '삐비빅. 알람이 다섯 번째로 울렸다. 3월 2일. 고3 첫날. 정문 앞 벚나무가 이상하게 일찍 피어 있었다. 교실 앞문이 열리고, 전학생이 들어왔다. 긴 흑발 끝에 보랏빛이 비쳤다. 그 애는 곧장 창가 맨 뒷자리로 걸어와, 내 옆에 앉으며 말했다. "…오랜만이야." 처음 보는 얼굴이었다. 그런데 왜인지, 가슴이 아팠다.' },
    true_daon: { title: '쿵짝, 그리고 무대', rank: 'S', bg: 'stage_concert', c: 'daon', e: 'laugh',
      t: '2년 뒤, 홍대 라이브 클럽. 실용음악과 드럼 전공 수석 입학생 민다온이 이끄는 밴드 "네 번째 멤버"의 첫 단독 공연. 매진이었다. 기타는 줄이 여섯 개 다 달린 채로, 무대 한가운데 서 있었다. 맨 앞줄에는 팔짱 낀 다온의 아버지가 응원봉을 흔들고 있었다. 앙코르 곡 직전, 다온이 마이크에 대고 외쳤다. "우리 기타 오빠가 중3 때 줄 끊어진 이야기, 해도 돼요?" 객석이 웃었다. 이번엔, 모두가 좋아서.' },
    normal_daon: { title: '박스 드럼의 여름', rank: 'A', bg: 'han_river', c: 'daon', e: 'smile',
      t: '다온은 고3이 되었다. 드럼 세트는 없지만, 매주 토요일 한강에는 박스 드럼과 기타가 나타난다. 대학생이 된 나와 수험생이 된 다온. 공부 사이사이의 한 시간짜리 버스킹. 다온은 모의고사 성적표 뒷면에 새 곡의 박자를 적어 온다. "선배, 수능 끝나면 진짜 드럼 살 거예요. 그때 진짜 무대 서요." 그 약속을, 나는 세상에서 제일 기다린다.' },
    bad_daon: { title: '리본 묶인 스틱', rank: 'BAD', bg: 'music_room', c: 'daon', e: 'sad',
      t: '한빛고 밴드부는 그해 봄 폐부되었다. 1998년산 드럼 세트는 창고로 옮겨졌다고 들었다. 내 방 책상 서랍에는 리본에 묶인 드럼 스틱 한 쌍이 있다. 한 번도 풀지 못했다. 가끔 길을 걷다 누군가 손가락으로 박자를 두드리는 소리가 들리면, 나도 모르게 돌아본다. 쿵, 쿵, 짝. 주황색 트윈테일은, 어디에도 없다.' },
    friend_taesik: { title: '벚꽃사진관', rank: 'A', bg: 'street_seoul', c: 'taesik', e: 'laugh',
      t: '동네 어귀의 "벚꽃사진관". 간판 글씨는 태식이 직접 썼는데, 삐뚤어져서 오히려 유명해졌다. 쇼윈도 한가운데에는 사진 한 장이 걸려 있다. 졸업식 날, 약속나무 아래서 교복 차림으로 어깨동무한 두 남자. 사람들이 물으면 태식은 말한다. "첫 손님이다. 공짜로 찍어 줬다." 연애는 여전히 둘 다 망했다. 열다섯 번째 짝사랑 이야기를, 나는 오늘도 사진관 소파에서 듣는다.' },
    solo_study: { title: '혼자 걸은 봄', rank: 'B', bg: 'sky_day', c: 'ssam', e: 'smile',
      t: '원하던 대학의 캠퍼스는 넓고 조용했다. 합격 소식을 전하자 강쌤은 "인생은 모의고사가 아니다. …근데 수능은 잘 봤네"라며 웃었다. 고3의 1년을 나는 오롯이 나를 위해 썼다. 후회는 없다. 다만 가끔, 캠퍼스 벚꽃길을 혼자 걸을 때면 생각한다. 그 해 약속나무 아래서, 누군가에게 무언가를 말했다면 어땠을까. 봄은 또 온다. 이번엔, 조금 다르게 걸어 보기로 한다.' },
    bad_alone: { title: '아무도 없는 교문', rank: 'BAD', bg: 'school_gate_sakura', c: 'ssam', e: 'sad',
      t: '졸업식 날, 약속나무 아래에는 아무도 오지 않았다. 옆집 소꿉친구는 언제부턴가 깨우러 오지 않았고, 학생회장은 내 이름을 벌점 명단에서만 기억했고, 창가 자리는 원래 비어 있었던 것 같고, 4층 음악실은 폐부되었다. 모두가 누군가와 사진을 찍는 교문 앞에서, 나는 휴대폰 카메라를 거꾸로 들고 혼자 웃었다. 1년은 생각보다 짧았다. 그리고 그 짧은 1년 동안, 나는 아무에게도 가지 않았다.' },
    secret_spring: { title: '여섯 명의 봄', rank: 'S', bg: 'school_gate_sakura', c: 'naeun', e: 'laugh',
      t: '4월, 벚꽃병원 507호. 문이 열리자 다섯 명이 한꺼번에 들이닥쳤다. 스케치북을 든 서하, 노트를 든 채원, 페인트 통을 든 다온, 카메라를 든 태식, 그리고 기타를 멘 나. 침대 위의 여자애가 눈을 크게 떴다가, 웃었다. "…다들, 기억하는구나." 수술은 성공했다. 채원의 기록장에는 "4월 12일, 비. 나은 기상 예보 적중."이라고 적혔다. 그해 여름, 태식이 찍은 사진 속에는 여섯 명이 바다에서 폭죽으로 원을 그리고 있다. 이번에는, 한 명도 빠짐없이.' },
