    blurb: '고3 첫날, 3월인데 교문 앞 약속나무가 피었다. 옆집 소꿉친구, 얼음 같은 학생회장, 미래를 아는 듯한 전학생, 폐부 직전 밴드부의 드러머 후배. 수능과 축제와 첫사랑 사이, 벚꽃이 지기 전에 전해야 할 한마디를 찾아라.',
    cover: { bg: 'school_gate_sakura', c: 'naeun', e: 'smile' },
    world: '무대는 서울의 평범한 인문계 고등학교 한빛고등학교. 정문 옆에는 백 년 된 벚나무 "약속나무"가 있고, "벚꽃이 지기 전에 그 아래서 한 말은 이루어진다"는 전설이 전해진다. 주인공은 3학년 2반 남학생으로, 이야기는 고3 개학식(3월 2일)부터 이듬해 2월 졸업식까지의 1년이다. 올해는 이상하게도 약속나무가 3월 개학식에 피어 1년 내내 지지 않는다. 담임은 물리 교사 강도윤, 절친은 사진부 박태식이다. 옆집 소꿉친구 윤서하, 학생회장 한채원, 3월의 전학생 이나은, 2학년 밴드부 드러머 민다온이 주요 인물이다. 한국 고3의 일상(모의고사, 야자, 수학여행, 체육대회, 여름 보충, 축제 "한빛제", 수능, 졸업식)이 배경이며, 학교 건너편에는 벚꽃병원이 있다. 모든 로맨스는 풋풋하고 순수한 고등학생의 감정 선을 지킨다.',
